#include <iostream>
#include <vector>
#include <unordered_map>
#include <bitset>
#include <cstring>
#include <algorithm>
using namespace std;

const int MOD = 1000000007;
using BSet = bitset<128>;

int N, cnt;
int P[7][7];
int iv100;

BSet init_state;

unordered_map<BSet, int> state_id;
vector<vector<int>> transition;
vector<int> state_dp[2];
vector<int> probability_cache;

int mod_pow(long long base, int exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return (int)result;
}

int compute_state_id(BSet bs) {
    if (state_id.find(bs) != state_id.end()) return state_id[bs];

    int new_id = state_id[bs] = ++cnt;
    BSet derived[7], current;

    // Precompute derived states
    for (int i = 0; i < N; ++i) {
        for (int mask = 0; mask < (1 << N); ++mask) {
            derived[i][mask | (1 << i)] = derived[i][mask | (1 << i)] | bs[mask];
        }
    }

    // Build transitions
    for (int mask = 0; mask < (1 << N); ++mask) {
        current = bs;
        for (int bit = 0; bit < N; ++bit) {
            if (mask >> bit & 1) current |= derived[bit];
        }
        transition[new_id][mask] = compute_state_id(current);
    }

    return new_id;
}

int main() {
    cin >> N;

    // Initialize transition table
    transition.resize(70003, vector<int>(128));

    init_state.set(0);
    compute_state_id(init_state);
    iv100 = mod_pow(100, MOD - 2);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> P[i][j];
        }
    }

    // Initialize DP
    state_dp[0].assign(70003, 0);
    state_dp[1].assign(70003, 0);
    state_dp[0][1] = 1;

    probability_cache.resize(1 << N);

    int current = 0;
    for (int stage = 0; stage < N; ++stage) {
        // Precompute probabilities for this stage
        for (int mask = 0; mask < (1 << N); ++mask) {
            probability_cache[mask] = 1;
            for (int k = 0; k < N; ++k) {
                int prob_val = (mask >> k & 1) ? P[stage][k] : (100 - P[stage][k]);
                probability_cache[mask] = (1LL * probability_cache[mask] * iv100 % MOD) * prob_val % MOD;
            }
        }

        // Clear next state DP
        fill(state_dp[current ^ 1].begin(), state_dp[current ^ 1].end(), 0);

        // Process transitions
        for (int s = 1; s <= cnt; ++s) {
            if (state_dp[current][s]) {
                for (int mask = 0; mask < (1 << N); ++mask) {
                    int next_s = transition[s][mask];
                    state_dp[current ^ 1][next_s] = (state_dp[current ^ 1][next_s] + 
                                                     1LL * state_dp[current][s] * probability_cache[mask]) % MOD;
                }
            }
        }

        current ^= 1;
    }

    // Target state: all bits set
    BSet full_mask;
    full_mask.set();
    cout << state_dp[current][state_id[full_mask]] << endl;

    return 0;
}
